    entry(
        "Cap Stack Modeling", "Capital Stack Modeling",
        "Spreadsheet-based analysis of how senior debt, mezzanine, preferred equity, and common equity stack up in a deal — tests sensitivity to leverage, rates, and Sponsor returns.",
        "Spreadsheet analysis of senior debt, mezzanine, preferred equity, and common equity stacking.",
        "Cap Stack Modeling is core institutional Real Estate analysis. The model layers each financing tier: senior debt at 60% LTV with X% rate, Mezzanine at +10% LTV with Y% rate, Preferred Equity at +10% LTV with Z% required return, Common Equity for the rest. Sensitivity tests: Sponsor IRR under varying senior rates, debt-coverage minimums for refinance, breakage costs from prepayment, recourse triggers. The model surfaces Capital Stack optimisation: replace senior with cheaper insurance-company debt, add Mezzanine to reduce equity, swap preferred for common to capture more upside. Required output for every institutional deal memo.",
        ["NCREIF", "ULI"],
        indications=["Commercial", "Investment"],
        category="Market & Investment",
    ),
    entry(
        "Debt Yield", "",
        "A Lender's stress metric — NOI divided by loan amount — gauging the property's ability to service debt even under pessimistic Cap Rate scenarios.",
        "NOI divided by loan amount — Lender's stress metric for debt-coverage at varying Cap Rates.",
        "Debt Yield is the Lender-side alternative to LTV. Calculation: NOI ÷ loan amount. A property with $1M NOI and an $8M loan has 12.5% debt yield. Debt Yield is insensitive to Cap Rate movements — unlike LTV which depends on Sale Price. Conservative Commercial Lenders require minimum debt yields: 8-9% Multifamily, 9-10% Office, 10-11% Retail, 11-12% Hotel. The metric drove post-2008 CMBS Underwriting reform — pre-crisis Lenders priced almost entirely on LTV and DSCR, missing that Cap Rate Compression had pushed property values artificially high. Debt Yield rose to prominence as the structural-floor metric in commercial mortgage analysis.",
        ["NCREIF", "Investopedia"],
        indications=["Commercial", "Investment"],
        category="Financing & Lending",
    ),

    # --- Distress / special-situations ---------------------------
    entry(
        "Distressed Debt", "Distressed Mortgage",
        "A Mortgage trading below face value — the borrower's distress or the property's value collapse pushes the loan's market price down, attracting opportunistic buyers.",
        "Mortgage trading below face value due to borrower distress or property collapse.",
        "Distressed Debt investing in Real Estate revives in cycles: 1990 RTC, 2008-2012, 2023-2024 office. Investors buy the loan from the Lender (or Special Servicer in CMBS) at 40-70 cents on the dollar of face value, then pursue one of several exit paths: (1) Workout — renegotiate terms with the borrower, expecting partial loss but retention of cash-flowing asset. (2) Loan-to-Own — drive the borrower into Default and Foreclosure, taking the property at the loan's discounted basis. (3) Discounted payoff — borrower pays less than face but more than the investor's purchase price. Outcomes hinge on property quality, Sponsor cooperation, and special-servicer behaviour.",
        ["NCREIF", "Investopedia"],
        indications=["Investment", "Commercial"],
        category="Financing & Lending",
    ),
    entry(
        "Special Servicer", "Special Servicing",
        "The CMBS-specific party that takes over a distressed Mortgage from the regular Master Servicer — has discretion to modify, extend, sell, or foreclose on behalf of bondholders.",
        "CMBS party taking over distressed Mortgages from the Master Servicer — workout authority.",
        "Special Servicers manage CMBS Loans in or near Default. The Master Servicer handles routine collection on performing Loans; once a Loan is 60+ days delinquent or the borrower triggers specific events, control transfers to the Special Servicer. Major Special Servicers: LNR Partners (largest), Rialto Capital, KeyBank, Greystone. The Special Servicer's fiduciary duties run to the CMBS bondholders, not the Lender brand. Borrowers complain Special Servicers move too slowly, charge high fees, and prefer Foreclosure over modification. CMBS regulators and rating agencies monitor Special Servicer performance — failures during 2008-2012 produced major reform of conflict-of-interest rules.",
        ["NCREIF"],
        indications=["Commercial", "Investment"],
        category="Financing & Lending",
    ),
    entry(
        "Receiver", "Court-Appointed Receiver",
        "A court-appointed neutral third party that takes operational control of a distressed property pending Foreclosure resolution — collects Rent, pays expenses, prevents waste.",
        "Court-appointed neutral party taking control of a distressed property pending resolution.",
        "Receivership protects collateral value during litigation or workout. The Lender petitions the court for receiver appointment after Default; the court appoints a neutral professional (often a Property Manager firm or specialist). Receiver duties: take possession, collect Rent, pay critical Operating Expenses (Property Tax, utilities, insurance, payroll), prevent Tenant flight, maintain physical condition. Receivers report monthly to the court. Common in: Foreclosure proceedings on income-producing property where the borrower might mismanage during litigation, contested ownership cases, environmental cleanup orders. Receivership fees come out of property cash flow — typically $5,000-$25,000/month plus expenses.",
        ["Cornell LII"],
        indications=["Commercial", "Investment"],
        category="Financing & Lending",
    ),

